/* From Uiverse.io by alexruix - Tags: login, form */
.__UIV_SCOPE__ .main {
  position: relative;
  display: flex;
  flex-direction: column;
  background-color: #240046;
  max-height: 420px;
  overflow: hidden;
  border-radius: 12px;
  box-shadow: 7px 7px 10px 3px #24004628;
}

.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 24px;
}

/*checkbox to switch from sign up to login*/
.__UIV_SCOPE__ #chk {
  display: none;
}

/*Login*/
.__UIV_SCOPE__ .login {
  position: relative;
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .login label {
  margin: 25% 0 5%;
}

.__UIV_SCOPE__ label {
  color: #fff;
  font-size: 2rem;
  justify-content: center;
  display: flex;
  font-weight: bold;
  cursor: pointer;
  transition: .5s ease-in-out;
}

.__UIV_SCOPE__ .input {
  width: 100%;
  height: 40px;
  background: #e0dede;
  padding: 10px;
  border: none;
  outline: none;
  border-radius: 4px;
}

/*Register*/
.__UIV_SCOPE__ .register {
  background: #eee;
  border-radius: 60% / 10%;
  transform: translateY(5%);
  transition: .8s ease-in-out;
}

.__UIV_SCOPE__ .register label {
  color: #573b8a;
  transform: scale(.6);
}

.__UIV_SCOPE__ #chk:checked ~ .register {
  transform: translateY(-60%);
}

.__UIV_SCOPE__ #chk:checked ~ .register label {
  transform: scale(1);
  margin: 10% 0 5%;
}

.__UIV_SCOPE__ #chk:checked ~ .login label {
  transform: scale(.6);
  margin: 5% 0 5%;
}   
/*Button*/
.__UIV_SCOPE__ .form button {
  width: 85%;
  height: 40px;
  margin: 12px auto 10%;
  color: #fff;
  background: #573b8a;
  font-size: 1rem;
  font-weight: bold;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: .2s ease-in;
}

.__UIV_SCOPE__ .form button:hover {
  background-color: #6d44b8;
}
